#!/usr/bin/env bash
# `just blender-fixtures`: rebuild the Blender add-on's committed fixtures with a
# headless Blender and fail if they differ from the committed bytes.
#
#   blender_loop.*          a loop authored from scratch with the add-on, with art
#   blender_checker.png     its texture, generated by roundtrip.py (never disc pixels)
#   blender_loop.reexport.* that loop imported by the add-on and exported again
#   blender_motion.*        the loop with keyframed motion (an airship, a turning sun)
#   blender_motion.reexport.* that imported and exported again
#   oval.reexport.*         the committed oval, imported by the add-on and exported again
#
# It also runs `roundtrip.py line`, which asserts the racing-line paths and writes no fixture,
# `channels` (a trigger's oag_emit, an animation's oag_on, the track's published channels), `props` (mod_* properties, trigger Empties, Make trigger from mesh) and `effect` (a mod effect
# TOML previewed and exported again; needs the examples submodule).
#
# Needs Blender 4.2 or later on PATH (or $BLENDER). The gate does not run this (CI has
# no Blender); crates/trackfile/tests/blender.rs and trackfile_ground_truth.rs read the
# committed output. `--update` rewrites the fixtures instead of comparing.
# Nothing is installed: the add-on is registered from the repository, so the Blender
# user directory is untouched.
set -euo pipefail
cd "$(dirname "$0")/.."

blender=${BLENDER:-blender}
fixtures=crates/trackfile/tests/fixtures
out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT

run() {
  "$blender" -b --factory-startup --python-exit-code 1 \
    --python scripts/blender/roundtrip.py -- "$@"
}
"$blender" --command extension validate scripts/blender/oag_track
run loop "$out"
run line "$out"
run props "$out"
run channels "$out"
run effect assets/mods/examples/energy-turbo/fx/discharge.toml "$out"
run reexport "$out/blender_loop.track.toml" "$out"
run motion "$out"
run reexport "$out/blender_motion.track.toml" "$out"
run reexport "$fixtures/oval.track.toml" "$out"

status=0
for f in blender_loop.track.toml blender_loop.glb blender_checker.png \
  blender_loop.reexport.track.toml blender_loop.reexport.glb \
  blender_motion.track.toml blender_motion.glb \
  blender_motion.reexport.track.toml blender_motion.reexport.glb \
  oval.reexport.track.toml oval.reexport.glb; do
  if [ "${1:-}" = "--update" ]; then
    cp "$out/$f" "$fixtures/$f"
  elif ! cmp -s "$out/$f" "$fixtures/$f"; then
    echo "stale: $fixtures/$f (run: just blender-fixtures --update)" >&2
    status=1
  fi
done
[ "$status" = 0 ] && echo "blender fixtures: up to date"
exit $status
